L32_1.m_Talk_KOREA = "애버라인은 이 유적이 다른 세계로 통하는 문이라고 했는데……?"
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "アバーラインは、この遺跡が別の世界に通じる扉だと言っていたのですが……"
