L32_1.m_Talk_TWN = "艾伯林說這座遺跡是通往其他世界的門啊……？"
L32_1.m_Talk_DEU = "Abberline said this ruin was a door to another world..."
L32_1.m_Talk_FRA = "Abberline said this ruin was a door to another world..."
L33_1 = {}
L33_1.m_CutScenKey_Talk = "OMEN_CHARADE_INTERLUDE12@22#Talk"
L33_1.m_CutScenProcessKey = 0
L33_1.m_CutScenID = 8100131
L33_1.m_CutScenStrID = "OMEN_CHARADE_INTERLUDE12"
L33_1.m_bWaitClick = true
