L33_1.m_Face = "UNIT_IDLE"
L33_1.m_CharStrID = "NAYUBIN_SIX_NULL_NULL"
L33_1.m_Pos = "L"
L33_1.m_Talk_KOREA = "확실히… 세계를 넘나든다는 게 틀린 말은 아니지만, 이건 문 같은 게 아닙니다."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "確かに……世界を行き来するという点では概ね間違っていませんが、これは扉のようなものではありません。"
L33_1.m_Talk_ENG = "Well... it's not wrong to say it crosses worlds, but this isn't a door."
L33_1.m_Talk_TWN = "確實……說它能跨越世界並不算錯，但這並不是什麼門。"
L33_1.m_Talk_DEU = "Well... it's not wrong to say it crosses worlds, but this isn't a door."
L33_1.m_Talk_FRA = "Well... it's not wrong to say it crosses worlds, but this isn't a door."
L34_1 = {}
