L34_1.m_CharStrID = "NAYUBIN_SIX_NULL_NULL"
L34_1.m_Pos = "L"
L34_1.m_Talk_KOREA = "이 단말기는 일종의 나침반 겉은 거죠. 함선을 안내하는."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "この端末は一種の羅針盤です。艦船を導くためのね。"
L34_1.m_Talk_ENG = "This terminal is more like a kind of compass. One that guides a ship."
L34_1.m_Talk_TWN = "這台終端，更像是一種用來引導艦船的指南針。"
L34_1.m_Talk_DEU = "This terminal is more like a kind of compass. One that guides a ship."
L34_1.m_Talk_FRA = "This terminal is more like a kind of compass. One that guides a ship."
L35_1 = {}
