L35_1.m_Pos = "R"
L35_1.m_Crash = 15
L35_1.m_Talk_KOREA = "함선? 그럼, 이 유적이 배의 일부였다는 뜻인가요?"
L35_1.m_fTalkTime = 0.03
L35_1.m_Talk_JPN = "艦船？　ではこの遺跡は船の一部だったということですか？"
L35_1.m_Talk_ENG = "A ship? Then does that mean this ruin was part of a ship?"
L35_1.m_Talk_TWN = "艦船？所以這座遺跡其實是船的一部分嗎？"
L35_1.m_Talk_DEU = "A ship? Then does that mean this ruin was part of a ship?"
L35_1.m_Talk_FRA = "A ship? Then does that mean this ruin was part of a ship?"
