L37_1.m_Talk_KOREA = "그래요, 우리 세계는 이런 좌초된 함선을 <color=#ffd34c>로스트쉽</color>이라고 부릅니다."
L37_1.m_fTalkTime = 0.03
L37_1.m_Talk_JPN = "そう。僕たちの世界ではこのような座礁した艦船のことを<color=#ffd34c>ロストシップ</color>と呼んでいます。"
L37_1.m_Talk_ENG = "Yes. In our world, we call wrecked ships like this a <color=#ffd34c>Lost Ship</color>."
