L20_1 = "엄밀히 말하면, 당신은 세피라를 비틀어 만들어낸 제 창작물에 불과해요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "厳密に言えば、あなたは私がセフィラを歪ませて作り出した仮初の存在に過ぎません。"
