L20_1.m_Face = "UNIT_PRIDE"
L20_1.m_CharStrID = "SWAN_SWANSONG_NPC_NULL"
L20_1.m_Pos = "R"
L21_1 = "비록 만들어진 캐릭터에 불과하더라도, 마음이 담기면 그 또한 저의 일부예요."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "作られたキャラクターに過ぎないとしても、心が宿ればそれは私の一部です。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Even if I'm just a created character, if my heart is in it, then it's also a part of me."
L20_1.m_Talk_ENG = L21_1
L21_1 = "即使只是被創造出來的角色，只要注入感情，那也是我的一部分。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "Even if I'm just a created character, if my heart is in it, then it's also a part of me."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Even if I'm just a created character, if my heart is in it, then it's also a part of me."
L20_1.m_Talk_FRA = L21_1
