L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "L"
L22_1 = "이 극장에서 모든 기억을 인계 받는 순간, 당신은 더는 당신이 아니게 될지도 몰라요."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "この劇場ですべての記憶を引き継ぐ瞬間、あなたはあなたでなくなるかもしれません。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "The moment you inherit all memories in this theater, you may no longer be you."
L21_1.m_Talk_ENG = L22_1
L22_1 = "在這座劇場，當你繼承所有記憶的瞬間，或許你就不再是你自己了。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "The moment you inherit all memories in this theater, you may no longer be you."
L21_1.m_Talk_DEU = L22_1
L22_1 = "The moment you inherit all memories in this theater, you may no longer be you."
L21_1.m_Talk_FRA = L22_1
